5	import 'package:meta/meta.dart';
6	
7	import 'file_system.dart';
8	import 'logger.dart';
9	
10	/// Project is generated from a template on Flutter project creation.
11	/// Sometimes (due to behavior changes in Xcode, Gradle, etc) these files need to be altered
12	/// from the original template.
13	abstract class ProjectMigrator {
14	  ProjectMigrator(this.logger);
15	
16	  @protected
17	  final Logger logger;
18	
19	  /// Returns whether migration was successful or was skipped.
20	  bool migrate();
21	
22	  /// Return null if the line should be deleted.
23	  @protected
24	  String migrateLine(String line) {
25	    return line;
26	  }
27	
28	  @protected
29	  void processFileLines(File file) {
30	    final List<String> lines = file.readAsLinesSync();
31	
32	    final StringBuffer newProjectContents = StringBuffer();
33	    final String basename = file.basename;
34	
35	    bool migrationRequired = false;
36	    for (final String line in lines) {
37	      final String newProjectLine = migrateLine(line);
38	      if (newProjectLine == null) {
39	        logger.printTrace('Migrating $basename, removing:');
40	        logger.printTrace('    $line');
41	        migrationRequired = true;
42	        continue;
43	      }
44	      if (newProjectLine != line) {
45	        logger.printTrace('Migrating $basename, replacing:');
46	        logger.printTrace('    $line');
47	        logger.printTrace('with:');
48	        logger.printTrace('    $newProjectLine');
49	        migrationRequired = true;
50	      }
51	      newProjectContents.writeln(newProjectLine);
52	    }
53	
54	    if (migrationRequired) {
55	      logger.printStatus('Upgrading $basename');
56	      file.writeAsStringSync(newProjectContents.toString());
57	    }
58	  }
59	}
60	
61	class ProjectMigration {
62	  ProjectMigration(this.migrators);
63	
64	  final List<ProjectMigrator> migrators;
65	
66	  bool run() {
67	    for (final ProjectMigrator migrator in migrators) {
68	      if (!migrator.migrate()) {
69	        // Migration failures should be more robust, with transactions and fallbacks.
70	        // See https://github.com/flutter/flutter/issues/12573 and
71	        // https://github.com/flutter/flutter/issues/40460
72	        return false;
73	      }
74	    }
75	    return true;
76	  }
77	}
