22	void main () {
23	  group('iOS migration', () {
24	    MockUsage mockUsage;
25	    setUp(() {
26	      mockUsage = MockUsage();
27	    });
28	
29	    testWithoutContext('migrators succeed', () {
30	      final FakeIOSMigrator fakeIOSMigrator = FakeIOSMigrator(succeeds: true);
31	      final ProjectMigration migration = ProjectMigration(<ProjectMigrator>[fakeIOSMigrator]);
32	      expect(migration.run(), isTrue);
33	    });
34	
35	    testWithoutContext('migrators fail', () {
36	      final FakeIOSMigrator fakeIOSMigrator = FakeIOSMigrator(succeeds: false);
37	      final ProjectMigration migration = ProjectMigration(<ProjectMigrator>[fakeIOSMigrator]);
38	      expect(migration.run(), isFalse);
39	    });
40	
41	    group('remove framework linking and embedding migration', () {
42	      MemoryFileSystem memoryFileSystem;
